CREATE TABLE IF NOT EXISTS currency (code TEXT PRIMARY KEY, symbol TEXT NOT NULL, symbol_native TEXT NOT NULL, name TEXT NOT NULL, decimal_digits INTEGER NOT NULL DEFAULT 0, rounding NUMERIC NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rbac_role (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_rbac_role_name_unique ON rbac_role(name) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS rbac_policy (id TEXT PRIMARY KEY, key TEXT NOT NULL, resource TEXT NOT NULL, operation TEXT NOT NULL, name TEXT, description TEXT, metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS IDX_rbac_policy_key_unique ON rbac_policy(key) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS IDX_rbac_policy_resource ON rbac_policy(resource) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS IDX_rbac_policy_operation ON rbac_policy(operation) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS rbac_role_policy (id TEXT PRIMARY KEY, role_id TEXT NOT NULL REFERENCES rbac_role(id), policy_id TEXT NOT NULL REFERENCES rbac_policy(id), metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS IDX_rbac_role_policy_role_id ON rbac_role_policy(role_id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS IDX_rbac_role_policy_policy_id ON rbac_role_policy(policy_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS IDX_rbac_role_policy_role_id_policy_id_unique ON rbac_role_policy(role_id,policy_id) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS rbac_role_parent (id TEXT PRIMARY KEY, role_id TEXT NOT NULL REFERENCES rbac_role(id), parent_id TEXT NOT NULL REFERENCES rbac_role(id), metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS IDX_rbac_role_parent_role_id ON rbac_role_parent(role_id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS IDX_rbac_role_parent_parent_id ON rbac_role_parent(parent_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS IDX_rbac_role_parent_role_id_parent_id_unique ON rbac_role_parent(role_id,parent_id) WHERE deleted_at IS NULL;
